ruleSearch.lastChapter:
@js:
eval(String(source.bookSourceComment));
if(lastChapter == 1){
api_path = "http://a.lc1001.com/app/info/bookcata?bID={{$.KEYID}}&consumerKey=LCREAD_ANDROID&isUpdate=0";
method = "GET";
api_Params = "&token=0";
eval(String(source.loginUrl));u();
$ = JSON.parse(java.ajax(url)).DATA.BOOKCATA;
length = $.length;
CHAPTERS = $[length-1].CHAPTERS;
length = CHAPTERS.length;
lastChapter = CHAPTERS[length-1].CNAME;
}
else { lastChapter = "";}

ruleToc.chapterList:
@js:
data = JSON.parse(result).DATA.BOOKCATA;
list = [];

for(i in data){
		name = "🏮〖"+data[i].VNAME+"〗🏮";
	list.push({
			text: name,
			href: null,
			volume: true
	})

data[i].CHAPTERS.forEach($=> {
   text = $.CNAME;
   chapter = $.chapter;
   cid = $.CID;
   isvc = $.ISVC;
   try{
$ = JSON.parse(JSON.stringify(source.getLoginHeaderMap()));
uID = $.uid;
token = $.token;
}
catch(e){ uID = "0"; token = "0";	}

if(isvc==0){
u = "/app/book/pubchapter";
}else{
u = "/app/book/vipchapter";
}
api_path = `http://a.lc1001.com${u}?bID=${java.get('BID')}&cID=${cid}&consumerKey=LCREAD_ANDROID`;
method = "GET";
api_Params = "&token="+token;
eval(String(source.loginUrl));u();
    list.push({
			text: text,
			href: url	,
			isvc: isvc
	});
});
}
list

