ruleToc.chapterList:
@js:
var m=baseUrl.match(/\/(song|playlist)\/([a-z]+)\/(\d+)\?/);
var arr=[];
if(m&&m[1]=='song'){
  var nm=baseUrl.match(/name=([^&]+)/);
  var name=nm?decodeURIComponent(nm[1]):'歌曲';
  var u='https://fy-musicbox-api.mu-jie.cc/meting/?server='+m[2]+'&type=url&id='+m[3]+',{"headers":{"Referer":"https://mu-jie.cc/"}}';
  arr.push(JSON.stringify({name:name,url:u,itemId:m[3]}));
}else{
  var d=(typeof result==='string')?JSON.parse(result):result;
  var tracks=(d&&d.tracks)||[];
  for(var i=0;i<tracks.length;i++){
    var t=tracks[i];t.url=t.url+',{"headers":{"Referer":"https://mu-jie.cc/"}}';arr.push(JSON.stringify(t));
  }
}
arr;

